cd /home/jess/Documents/primary_juvenile_meta-analysis; S=/tmp/claude-1000/-home-jess-Documents-primary-juvenile-meta-analysis/79bf9038-6b6c-45e5-90de-1cf92dea0c2b/scratchpad
cat > $S/kub_build.py <<'E'
import re,json,sys
sys.path.insert(0,sys.argv[1]); from out import append
WRITE=len(sys.argv)>2 and sys.argv[2]=='write'
rows=json.load(open(sys.argv[1]+'/kub_rows.json'))
SRC="Kubiak, P. J. (2009). Fire responses of bushland plants after the January 1994 wildfires in northern Sydney. Cunninghamia, 11(1), 131-165."
FN="Kubiak Cunn 2009"
LCR,NL="Lane Cove River","Narrabeen Lagoon"
flag=[]
def dash(s): return s.replace('–','-').replace('—','-')
NUM=r'(\d+(?:\.\d+)?)'
def parse(cell):
    """return (lo,hi,unit,extra_notes,ok) for a time cell; ok False -> notes only"""
    s=dash(cell).replace('**','').strip()
    if not s: return None
    if '<u>' in s: return ('U',s)
    if re.search(r'buds|m\.i\.f|grn|green|[Nn]ote|[Ll]eaves|[Rr]esprouted|fruit|pop\.|ripe|ri\b|ri\.|imm',s) and not re.search(r'a few fruit|a small pop',s):
        return ('N',s)
    m=re.match(r'(c\.\s?)?(\?)?'+NUM+r'(?:-'+NUM+r')?(\+)?\s?(w|y)?',s)
    if not m: return ('N',s)
    lo,hi,unit=m.group(3),m.group(4),m.group(6)
    if not unit:
        u=re.search(r'\d\s?(w|y)',s); unit=u.group(1) if u else None
    if not unit: return ('N',s)
    marks=[]
    if m.group(1): marks.append('c.')
    if m.group(2) or '?' in s: marks.append('?')
    if m.group(5): marks.append('+')
    rest=s[m.end():].strip()
    return ('V',lo,hi,unit,marks,rest)
def yrs(v,unit):
    if unit=='y': return v
    x=round(float(v)/52,3); return ('%.3f'%x).rstrip('0').rstrip('.')
def fmt(lo,hi,conv,unit):
    f=(lambda v: yrs(v,unit)) if conv else (lambda v:v)
    return f(lo)+('-'+f(hi) if hi else '')
UN={'w':'weeks','y':'years'}
def fr_map(c):
    c=dash(c).strip()
    if c=='R': return 'resprouter'
    if c=='K': return 'obligate'
    return re.sub(r'\s*([?/;,()])\s*',r'\1',c)
LEG="fire response codes (p. 145): R = majority of adult plants resprouted; K = majority killed; r = small proportion resprouted; k = small proportion killed; p = probably (80-90% sure); ? = possibly (50-70% sure); responses after 100% leaf scorch"
def name_split(sp):
    notes=[]; printed=sp
    native=''
    if sp.startswith('(*?)'): sp=sp[4:]; notes.append("name printed as '%s'; exotic status uncertain"%printed)
    elif sp.startswith('*'): sp=sp[1:]; native='exotic'
    m=re.search(r'\s*\(syn\. ([^)]*)\)',sp)
    if m: notes.append('synonym printed: '+m.group(1)); sp=sp[:m.start()]+sp[m.end():]
    for q in ('(s.lat.)','(s.str.)'):
        if q in sp: sp=sp.replace(q,'').strip(); notes.append("name printed with '%s'"%q)
    sp=sp.replace('“','').replace('”','')
    sp=dash(sp)
    if '?' in sp:
        notes.append("name printed as '%s'"%dash(printed)); sp=sp.replace('?(','').replace('?','').replace(')','')
    elif printed!=sp and '“' in printed: notes.append("name printed as '%s'"%printed)
    p=sp.split()
    g=p[0]; rest=p[1:]
    sub=''
    for i,w in enumerate(rest):
        if w in('subsp.','var.','f.','cv.'):
            sub=' '.join(rest[i:]); rest=rest[:i]; break
    spp=' '.join(rest)
    return g,spp,sub,native,notes
out=[];counts={'species':0,'norow':[]}
for r in rows:
    page,fam,sp,peak,lcr,nl,seed,flr,fls,frr,frs,pjp,sjp=r
    counts['species']+=1
    g,spe,sub,native,nn=name_split(sp)
    base=dict(Genus=g,Species=spe,subsp=sub,scientific_name=(g+' '+spe).strip(),native_status=native,Family=fam,Source=SRC,File_name=FN,
              Fire_type='wildfire',Fire_season_categorical='Summer',Fire_severity_categorical='High')
    notes=list(nn)
    if native: notes.append("'*' = exotic species (p. 145)")
    tv={}; tn=[]
    # site codes (some cells hold text notes)
    codes={}
    for site,c in ((LCR,lcr),(NL,nl)):
        c=c.strip()
        if not c: continue
        m=re.match(r'^(\?|p)?[RKrk](\(1\))?(/\??[RKrk])?(\s?;\s?r)?(-m\.i\.f)?',dash(c).replace('? ','?').replace('/ ','/'))
        if m and m.group(0):
            code=m.group(0); extra=dash(c).replace('? ','?').replace('/ ','/')[len(code):].strip()
            codes[site]=fr_map(code)
            if extra: tn.append(f"{site} cell also printed '{extra}'")
            if code!=c.replace('? ','?').replace('/ ','/'): pass
        else:
            tn.append(f"{site} column text: '{dash(c)}'")
    if peak: tn.append(f"subjective post-fire peak estimate {dash(peak)} (y = years)")
    if seed: tn.append(f"seedlings first observed {dash(seed)} after fire (w = weeks; adv = advanced seedlings)")
    # flowering
    for col,cell,lab in (('Time to first flower production resprout_repr3a',flr,'first flowering of resprouts'),('Age at first flower production from seed_repr3',fls,'first flowering from seed')):
        p=parse(cell)
        if not p: continue
        if p[0]=='U':
            if lab.endswith('seed'): continue
            tn.append(f"first flowering {dash(cell).replace('<u>','').replace('</u>','').replace('**','')} printed bridging Resp and Seed columns (unclear whether from seed or resprouts)")
            continue
        if p[0]=='N':
            tn.append(f"{lab} cell printed '{dash(cell).replace('**','')}' (not filled)"); continue
        _,lo,hi,unit,marks,rest=p
        tv[col]=fmt(lo,hi,True,unit)
        if unit=='w': tn.append(f"{col} converted from {dash(cell).replace('**','').split(',')[0].strip() if not hi else lo+'-'+hi+' weeks'}".replace(' w',' weeks') if False else f"{col} converted from {lo+('-'+hi if hi else '')} weeks")
        if marks or rest or '**' in cell or ',' in cell:
            tn.append(f"{lab} printed as '{dash(cell).replace('**','')}'"+(" (bold = sizable proportion of population flowering)" if '**' in cell else '')+(" ('c.' = approximately)" if 'c.' in marks else '')+(" ((1) = one plant)" if '(1)' in cell else ''))
    for col,cell,lab in (('First fruiting Resp',frr,'first fruiting of resprouts'),('First fruiting Seed',frs,'first fruiting from seed')):
        if not cell: continue
        c=dash(cell).replace('**','')
        if '<u>' in c:
            if lab.endswith('seed'): continue
            tn.append(f"first fruiting or spore production {c.replace('<u>','').replace('</u>','')} printed bridging Resp and Seed columns")
        else: tn.append(f"{lab} (or spore production) {c}")
    for col,cell,conv in (('primary_juvenile_period',pjp,True),('secondary_juvenile_period',sjp,False)):
        if not cell: continue
        c=dash(cell)
        if c=='At least 5 years': p=('V','5',None,'y',[],'');
        elif c=='Less than 1 year': p=('V','<1',None,'y',[],'')
        else: p=parse(cell)
        if p[0]!='V': tn.append(f"{col} cell printed '{c}' (not filled)"); flag.append((sp,col,c)); continue
        _,lo,hi,unit,marks,rest=p
        if lo=='<1': tv[col]='<1'
        else: tv[col]=fmt(lo,hi,conv,unit)
        if conv and unit=='w': tn.append(f"{col} converted from {lo+('-'+hi if hi else '')} weeks")
        if not conv: tv['Time_unit']=UN[unit]
        if marks or rest or c!=(lo+('-'+hi if hi else '')+unit):
            tn.append(f"{col.split('_')[0]} juvenile period printed as '{c}'"+(" ('c.' = approximately)" if 'c.' in marks else '')+(" ((shd) = shedding seed or spores)" if 'shd' in c else ''))
            if '+' in marks or '?' in marks: flag.append((sp,col,c))
    tn.append(f"Appendix 1, p. {page}")
    has_t=any(k for k in tv if k!='Time_unit')
    sites=list(codes)
    def mk(loc,coords,fr,extra):
        d=dict(base); d['Location_name']=loc
        if coords: d['Latitude']='-33.75'; d['Longitude']='151.0833'
        if fr: d['fire_response categorical_surv1']=fr
        d['Notes']='; '.join(notes+extra); return d
    common=[LEG] if codes else []
